class ZimmButton extends HTMLElement {
  static get observedAttributes() {
    return ['variant', 'size', 'label', 'disabled'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback() { this._render(); }

  _render() {
    const variant  = this.getAttribute('variant') || 'primary';
    const size     = this.getAttribute('size') || 'large';
    const label    = this.getAttribute('label') || 'Button';
    const disabled = this.hasAttribute('disabled');

    const p  = variant === 'primary';
    const lg = size === 'large';

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-block; }

        button {
          position: relative;
          display: inline-flex;
          align-items: center;
          justify-content: center;
          gap: var(--zimm-size-action-gap);
          min-width: 80px;
          overflow: clip;
          cursor: pointer;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          text-transform: uppercase;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;

          height:      ${lg ? 'var(--zimm-size-action-height-lg)'    : 'var(--zimm-size-action-height-md)'};
          padding:     0 ${lg ? 'var(--zimm-size-action-padding-h-lg)' : 'var(--zimm-size-action-padding-h-md)'};
          font-size:   ${lg ? 'var(--zimm-font-size-2xs)'            : 'var(--zimm-font-size-3xs)'};
          line-height: ${lg ? 'var(--zimm-font-lineheight-3xs)'      : 'var(--zimm-font-lineheight-2xs)'};

          background:   ${p ? 'var(--zimm-color-action-primary-bg-default)' : 'transparent'};
          color:        ${p ? 'var(--zimm-color-action-primary-text)'       : 'var(--zimm-color-action-secondary-text)'};
          border:       ${p ? 'none'
                            : 'var(--zimm-border-width-default) solid var(--zimm-color-action-secondary-border)'};
        }

        button:hover:not(:disabled) {
          background: ${p ? 'var(--zimm-color-action-primary-bg-hover)'
