class ZimmFooter extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this._render();
  }

  _render() {
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        * { box-sizing: border-box; }

        footer {
          background-color: var(--zimm-color-bg-inverse);
          width: 100%;
        }

        /* ---- Main grid: mobile default ---- */
        .main {
          display: grid;
          grid-template-columns: 1fr;
          grid-template-rows: auto auto auto;
          padding: var(--zimm-scale-1200) var(--zimm-scale-800) 0;
        }

        .subscribe { grid-column: 1; grid-row: 1; padding-bottom: var(--zimm-scale-600); }
        .links     { grid-column: 1; grid-row: 2; }
        .logo-area { grid-column: 1; grid-row: 3; padding: var(--zimm-scale-1000) 0; }

        /* ---- Subscribe ---- */
        .label {
          margin: 0 0 var(--zimm-scale-600);
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: normal;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color: var(--zimm-color-text-inverse-muted);
        }

        .body-text {
          margin: 0 0 var(--zimm-scale-1200);
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: var(--zimm-font-lineheight-2xs);
          color: var(--zimm-color-text-inverse);
        }

        .email-field {
          display: flex;
          align-items: center;
          justify-content: space-between;
          border-bottom: 1px solid var(--zimm-color-text-inverse);
          padding-bottom: var(--zimm-scale-200);
        }

        .email-input {
          flex: 1;
          background: transparent;
          border: none;
          outline: none;
          padding: 0;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-regular);
          font-size: var(--zimm-font-size-2xs);
          color: var(--zimm-color-text-inverse);
        }

        .email-input::placeholder {
          color: var(--zimm-color-text-inverse);
          opacity: 1;
        }

        .email-submit {
          background: none;
          border: none;
          padding: 0;
          cursor: pointer;
          display: flex;
          align-items: center;
          color: var(--zimm-color-text-inverse);
        }

        .email-submit:focus-visible {
          outline: 2px solid var(--zimm-color-text-inverse);
          outline-offset: 2px;
        }

        /* ---- Links: mobile 2-col grid ---- */
        .links {
          display: grid;
          grid-template-columns: 1fr 1fr;
          column-gap: var(--zimm-scale-600);
          row-gap: var(--zimm-scale-600);
          padding: var(--zimm-scale-1200) 0;
          border-top: 1px solid var(--zimm-color-grey-700);
          border-bottom: 1px solid var(--zimm-color-grey-700);
        }

        /* Mobile column placement: About + Contact left, Help right */
        .link-group:nth-child(1) { grid-column: 1; grid-row: 1; }
        .link-group:nth-child(2) { grid-column: 1; grid-row: 2; }
        .link-group:nth-child(3) { grid-column: 2; grid-row: 1 / span 2; }

        .group-label {
          margin: 0 0 var(--zimm-scale-600);
          font-family: var(--zimm-font-family-body);
