          .legal-link { display: inline; }

          .bottom-bar {
            padding: var(--zimm-scale-600) var(--zimm-scale-1000);
          }
        }

        /* ---- Desktop: 1024px+ ---- */
        @media (min-width: 1024px) {
          .links { gap: var(--zimm-scale-1200); }
        }
      </style>

      <footer role="contentinfo">
        <div class="main">

          <div class="subscribe">
            <p class="label">Stay in Touch</p>
            <p class="body-text">Subscribe to receive news on our latest collections, products, fashion shows and collaborations.</p>
            <div class="email-field">
              <input type="email" class="email-input" placeholder="Email" aria-label="Email address">
              <button class="email-submit" type="button" aria-label="Subscribe">
                <zimm-icon type="arrow-link" size="16" aria-hidden="true"></zimm-icon>
              </button>
            </div>
          </div>

          <div class="logo-area">
            <zimm-logo variant="inverse"></zimm-logo>
          </div>

          <div class="links">
            <div class="link-group">
              <p class="group-label">About</p>
              <ul>
                <li><a href="#">Our Story</a></li>
                <li><a href="#">Careers</a></li>
                <li><a href="#">Sustainability</a></li>
                <li><a href="#">Acknowledgement of Country</a></li>
              </ul>
            </div>
            <div class="link-group">
              <p class="group-label">Contact</p>
              <ul>
                <li><a href="#">866 688 5656</a></li>
                <li><a href="#">Chat with Us</a></li>
                <li><a href="#">Store Finder</a></li>
                <li><a href="#">Socials</a></li>
              </ul>
            </div>
            <div class="link-group">
              <p class="group-label">Help</p>
              <ul>
                <li><a href="#">Orders &amp; Returns</a></li>
                <li><a href="#">Submit a Return</a></li>
                <li><a href="#">FAQs</a></li>
                <li><a href="#">Care Guide</a></li>
                <li><a href="#">Appointments</a></li>
                <li><a href="#">Gifting</a></li>
                <li><a href="#">Brand Protection</a></li>
              </ul>
            </div>
          </div>

        </div>

        <div class="bottom-bar">
          <span class="locale">United States (USD) / Eng</span>
          <div class="legal">
            <span>Copyright &copy; 2026 Zimmermann</span>
            <a href="#" class="legal-link">Accessibility</a>
            <a href="#" class="legal-link">Privacy Policy</a>
            <a href="#" class="legal-link">Terms &amp; Conditions</a>
            <a href="#" class="legal-link">Modern Slavery</a>
            <a href="#" class="legal-link">Cookie Settings</a>
          </div>
        </div>
      </footer>
    `;
  }
}

customElements.define('zimm-footer', ZimmFooter);

