class ZimmProductCard extends HTMLElement {
  static get observedAttributes() {
    return ['product-name', 'price', 'tag', 'show-button', 'show-price', 'show-tag', 'show-share'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback() { this._render(); }

  _render() {
    const productName = this.getAttribute('product-name') || '';
    const price       = this.getAttribute('price') || '';
    const tag         = this.getAttribute('tag') || '';
    const showButton  = this.hasAttribute('show-button');
    const showPrice   = this.hasAttribute('show-price');
    const showTag     = this.hasAttribute('show-tag') && tag;
    const showShare   = this.hasAttribute('show-share');

    this.shadowRoot.innerHTML = `
      <style>
        :host {
          display: block;
          width: 100%;
        }

        .card {
          display: flex;
          flex-direction: column;
        }

        .image-area {
          position: relative;
          width: 100%;
          aspect-ratio: 288 / 440;
          overflow: hidden;
          background: var(--zimm-color-bg-01);
        }

        ::slotted(img),
        ::slotted(picture) {
          display: block;
          width: 100%;
          height: 100%;
          object-fit: cover;
        }

        .image-overlay {
          position: absolute;
          inset: 0;
          pointer-events: none;
        }

        .tag {
          position: absolute;
          top: var(--zimm-scale-500);
          left: var(--zimm-scale-500);
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: var(--zimm-font-lineheight-2xs);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
          pointer-events: auto;
        }

        .image-actions {
          position: absolute;
          top: var(--zimm-scale-500);
          right: var(--zimm-scale-500);
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: var(--zimm-scale-200);
          pointer-events: auto;
        }

        .card-body {
          display: flex;
          flex-direction: column;
          gap: var(--zimm-scale-800);
          padding: var(--zimm-scale-800) var(--zimm-scale-1000);
        }

        .card-info {
          display: flex;
          flex-direction: column;
          gap: var(--zimm-scale-200);
        }

        .product-name {
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-3xs);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
        }

        .price {
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-2xs);
          color: var(--zimm-color-text-default);
        }

        zimm-button {
          display: block;
          width: 100%;
        }

        zimm-icon {
          cursor: pointer;
        }
      </style>

      <div class="card">
        <div class="image-area">
          <slot name="image"></slot>
          <div class="image-overlay">
            ${showTag ? `<span class="tag">${tag}</span>` : ''}
            <div class="image-actions">
              ${showShare ? `<zimm-icon type="share" size="20" aria-label="Share"></zimm-icon>` : ''}
              <zimm-add-to-wishlist></zimm-add-to-wishlist>
            </div>
          </div>
        </div>
        <div class="card-body">
          <div class="card-info">
            ${productName ? `<span class="product-name">${productName}</span>` : ''}
            ${showPrice && price ? `<span class="price">${price}</span>` : ''}
          </div>
          ${showButton ? `<zimm-button variant="secondary" size="medium" label="Quick Add"></zimm-button>` : ''}
        </div>
      </div>
    `;
  }
}

customElements.define('zimm-product-card', ZimmProductCard);

